        else
            JH_why = tostring(r)
        end
    end
end
if not JH_fn then JH_fail("JAP HIGH: payload rejected - " .. JH_why) end
local JH_ok, JH_ferr = pcall(JH_fn)
if not JH_ok then
    JH_fail("japscript error: " .. tostring(JH_ferr))
end
